package com.hbm.machine.solarboiler;
import java.util.List;import net.minecraft.ChatFormatting;import net.minecraft.core.component.DataComponents;import net.minecraft.network.chat.Component;import net.minecraft.world.*;import net.minecraft.world.entity.ai.attributes.*;import net.minecraft.world.item.*;import net.minecraft.world.item.component.*;import net.minecraft.world.item.context.UseOnContext;
/** Source saved focus is true boiler coreY+1; source100m reach and >=45degree exact squared criterion. */
public final class MirrorToolItem extends Item {
 public MirrorToolItem(){super(new Properties().stacksTo(1).attributes(ItemAttributeModifiers.builder().add(Attributes.ATTACK_DAMAGE,new AttributeModifier(BASE_ATTACK_DAMAGE_ID,2,AttributeModifier.Operation.ADD_VALUE),net.minecraft.world.entity.EquipmentSlotGroup.MAINHAND).build()));}
 @Override public Component getName(ItemStack stack){return Component.translatable("item.mirror_tool.name");}
 @Override public void appendHoverText(ItemStack stack,TooltipContext context,List<Component> lines,TooltipFlag flag){for(String text:net.minecraft.locale.Language.getInstance().getOrDefault("item.mirror_tool.desc").split("\\$"))lines.add(Component.literal(text).withStyle(ChatFormatting.YELLOW));}
 @Override public InteractionResult useOn(UseOnContext context){var world=context.getLevel();var player=context.getPlayer();var pos=context.getClickedPos();var stack=context.getItemInHand();var block=world.getBlockState(pos).getBlock();if(block instanceof SolarBoilerBlock boiler){var core=boiler.findCore(world,pos);if(core!=null&&!world.isClientSide){CustomData.update(DataComponents.CUSTOM_DATA,stack,tag->{tag.putInt("posX",core.getX());tag.putInt("posY",core.getY()+1);tag.putInt("posZ",core.getZ());});if(player!=null)player.displayClientMessage(Component.translatable("item.mirror_tool.linked").withStyle(ChatFormatting.YELLOW),false);}return InteractionResult.SUCCESS;}if(block instanceof SolarMirrorBlock&&stack.has(DataComponents.CUSTOM_DATA)){if(!world.isClientSide&&world.getBlockEntity(pos) instanceof SolarMirrorBlockEntity mirror){var tag=stack.get(DataComponents.CUSTOM_DATA).copyTag();int x=tag.getInt("posX"),y=tag.getInt("posY"),z=tag.getInt("posZ"),dx=pos.getX()-x,dy=pos.getY()-y,dz=pos.getZ()-z;boolean withinReach=Math.sqrt((double)dx*dx+(double)dy*dy+(double)dz*dz)<=100,withinAngle=dx*dx+dz*dz<=dy*dy;if(!withinReach){if(player!=null)player.displayClientMessage(Component.translatable("item.mirror_tool.reach").withStyle(ChatFormatting.RED),false);}else if(!withinAngle){if(player!=null)player.displayClientMessage(Component.translatable("item.mirror_tool.angle").withStyle(ChatFormatting.RED),false);}else mirror.setTarget(x,y,z);}return InteractionResult.SUCCESS;}return InteractionResult.PASS;}
}
